    public function handle(): int
    {
        $client = Client::where('client_code', '097Y')->firstOrFail();
        $dry = (bool) $this->option('dry-run');
        $created = $updated = 0;
        foreach ($this->records as $r) {
            $existing = Project::withTrashed()->where('docket_number', $r['docket'])->first();
            if ($dry) { $this->line(($existing ? 'UPDATE ' : 'CREATE ').$r['docket'].' | '.$r['title']); continue; }
            DB::transaction(function () use ($client, $r, &$created, &$updated) {
                $project = Project::withTrashed()->where('docket_number', $r['docket'])->first();
                if ($project) {
                    if ($project->trashed()) $project->restore();
                    $project->update($this->payload($client->id, $r));
                    $updated++;
                } else {
                    $project = DB::transaction(fn () => app(ProjectController::class)->createFromImport(array_merge($this->payload($client->id, $r), ['record_mode'=>'existing','project_code'=>$r['docket'],'docket_number'=>$r['docket']])), 3);
                    $created++;
                }
                $project->update(['patent_granted' => $r['kind'] === 'granted']);
                if ($r['kind'] === 'granted' && $project->patent_application_id) {
                    PatentApplication::whereKey($project->patent_application_id)->update([
                        'grant_number' => $r['grant_number'] ?? $this->grantNumber($r['docket']),
                        'grant_date' => ($r['grant'] && $r['grant'] !== '-') ? $r['grant'] : null,
                        'legal_status' => 'Granted',
                    ]);
                }
                $this->mapStages($project, $r['kind']);
                $eventDate = ($r['grant'] && $r['grant'] !== '-') ? $r['grant'] : $r['filing'];
                $this->event($project, $r['kind'] === 'granted' ? 'granted' : ($r['kind'] === 'pct' ? 'pct_filed' : 'application_filed'), $eventDate, $r);
                if ($r['kind'] === 'pct') $this->event($project, 'published', $r['filing'], $r);
            });
        }
        $this->info("AppViewX import complete: {$created} created, {$updated} updated, ".count($this->records).' records processed.');
        return self::SUCCESS;
    }


    private function grantNumber(string $docket): string
    {
        return [
            '097Y001INCPT' => '385697', '097Y002INCPT' => '402249',
            '097Y006INCPT' => '520061', '097Y007INCPT' => '580347',
            '097Y008INCPT' => '587538', '097Y009INCPT' => '460945',
            '097Y010INCPT' => '489865', '097Y045INCPT' => '585126',
        ][$docket] ?? '';
    }

    private function payload(int $clientId, array $r): array
    {
        return ['client_id'=>$clientId,'project_name'=>$r['title'],'invention_title'=>$r['title'],'project_type'=>'Patent','case_type'=>$r['kind']==='granted'?'Granted Patent':'PCT International Application','application_number'=>$r['app'],'patent_office_code'=>$r['office'],'service_code'=>$r['service'],'filing_date'=>$r['filing'],'start_date'=>$r['filing'],'status'=>$r['kind']==='granted'?'Granted':'In Progress','original_docket'=>$r['raw'],'invention_number'=>substr($r['docket'],4,3),'notes'=>"Source status: {$r['status']}\nNext action: {$r['next']}\nInventors: {$r['inventors']}" ];
    }

    private function mapStages(Project $project, string $kind): void
    {
        $stages = $project->stages()->orderBy('sequence_order')->get();
        if ($kind === 'granted') {
            $stages->each(fn($s) => $s->update(['status'=>'Completed','actual_start_at'=>$s->actual_start_at ?: now(),'actual_end_at'=>$s->actual_end_at ?: now()]));
            if (!$stages->contains('stage_name','Granted')) ProjectStage::create(['project_id'=>$project->id,'stage_name'=>'Granted','status'=>'Completed','sequence_order'=>($stages->max('sequence_order') ?? 0)+1,'duration_days'=>0]);
            return;
        }
        $target = $stages->firstWhere('stage_name','International Publication Confirmed (18 months)');
        if (!$target) return;
        $stages->each(function($s) use ($target) { $s->update(['status'=>$s->sequence_order < $target->sequence_order ? 'Completed' : ($s->id === $target->id ? 'In Progress' : 'Pending')]); });
    }

    private function event(Project $project, string $type, string $date, array $r): void
    {
        $date = Carbon::parse($date)->toDateString();
        if (DocketEvent::where('project_id',$project->id)->where('event_type',$type)->whereDate('event_date',$date)->exists()) return;
        DocketRules::recordEvent($type, Carbon::parse($date), $project->id, $project->patent_application_id, "Imported from AppViewX status workbook. {$r['status']}. Next action: {$r['next']}", null);
    }
}
